"""The README results block generated by ``pii-guard eval report`` (LAB-1239)."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pytest

from pii_guard import cli
from pii_guard.eval.record import RecordError
from pii_guard.eval.report_readme import END, START, parse_spec, render_block, splice

ROOT = Path(__file__).resolve().parents[2]


def _index() -> dict[str, Any]:
    def snap(system: str, leak: float, p50: float, pooled: bool) -> dict[str, Any]:
        return {
            "fixture_set": "smoke",
            "system": system,
            "run_ids": [f"run-{system}"],
            "all": {
                "leak": leak,
                "documents": 3,
                "detect_p50_ms": p50,
                "latency_pooled": pooled,
                "over_masking": 0.0112 if system == "fast" else 0.3,
            },
        }

    return {
        "headline_set": "smoke",
        "fixture_sets": {"smoke": {"documents": {"de": 1, "en": 2}}},
        "snapshots": [snap("fast", 0.0, 45.2, False), snap("other", 0.1234, 88.0, True)],
    }


def _counts(system: str, leak: float, run_id: str) -> dict[str, Any]:
    return {
        "run_id": run_id,
        "dataset": "public",
        "system": {"key": system},
        "summary": {
            "documents": 7,
            "leak": {"value": leak},
            "over_masking": {"value": 0.278571},
        },
    }


SPEC = {
    "columns": [
        {"title": "Hand-written", "fixture_set": "smoke"},
        {"title": "Public", "dataset": "public"},
    ],
    "rows": [
        {"system": "fast", "label": "**Fast**", "short": "fast"},
        {"system": "other", "label": "Other", "short": "Other"},
        {"system": "missing", "label": "Never run", "p50": False},
    ],
}


def test_block_takes_the_latest_numbers_bolds_the_best_and_links_records() -> None:
    counts = [
        _counts("fast", 0.5, "old-fast"),
        _counts("fast", 0.02, "new-fast"),  # newer run of the same system wins
        _counts("other", 0.0191, "other"),
    ]
    block = render_block(_index(), counts, parse_spec(SPEC, "config"))
    assert "| Leak | Hand-written (de+en, 3 docs) | Public (7) |" in block
    assert "| **Fast** | **0.0 %** | 2.0 % |" in block
    assert "| Other | 12.3 % | **1.9 %** |" in block
    assert "| Never run | — | — |" in block
    assert "fast 45 ms, Other 88 ms*" in block
    assert "[Hand-written](eval/results/runs/run-fast.json)" in block
    assert "[Public](eval/datasets/results/new-fast.json)" in block
    assert "old-fast" not in block


def test_block_states_the_first_rows_over_masking_from_the_same_records() -> None:
    """LAB-1598: the README's over-masking figures come from the table's records, not prose."""
    counts = [_counts("fast", 0.02, "new-fast")]
    block = render_block(_index(), counts, parse_spec(SPEC, "config"))
    assert "Over-masking of the fast row: Hand-written 1.1 %, Public 27.9 %" in block
    no_over = [{**c, "summary": {"documents": 7, "leak": {"value": 0.1}}} for c in counts]
    assert "Over-masking of the fast row: Hand-written 1.1 % (" in render_block(
        _index(), no_over, parse_spec(SPEC, "config")
    )


def test_a_caveat_mark_on_the_best_cell_drops_the_bold() -> None:
    spec = json.loads(json.dumps(SPEC))
    spec["rows"][0]["marks"] = {"smoke": "†"}
    block = render_block(_index(), [], parse_spec(spec, "config"))
    assert "| **Fast** | 0.0 % † | — |" in block
    assert "| Other | 12.3 % | — |" in block


def test_splice_replaces_only_the_marked_block() -> None:
    doc = f"intro\n{START}\nold numbers\n{END}\noutro\n"
    assert splice(doc, "new\n", "README.md") == f"intro\n{START}\nnew\n{END}\noutro\n"
    with pytest.raises(RecordError, match="results:start"):
        splice("no markers\n", "new\n", "README.md")
    with pytest.raises(RecordError, match="results:start"):
        splice(doc + doc, "new\n", "README.md")


def test_bad_spec_is_rejected() -> None:
    with pytest.raises(RecordError):
        parse_spec({"columns": [{"title": "x"}], "rows": [{"system": "a", "label": "a"}]}, "c")
    with pytest.raises(RecordError):
        parse_spec({"columns": [], "rows": []}, "c")


def test_check_fails_on_a_hand_edited_readme_block(
    report_repo: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    config = report_repo / "docs/benchmarks/config.json"
    data = json.loads(config.read_text(encoding="utf-8"))
    data["readme"] = {
        "columns": [{"title": "Hand-written", "fixture_set": "smoke"}],
        "rows": [{"system": "rules", "label": "Rules", "short": "rules"}],
    }
    config.write_text(json.dumps(data), encoding="utf-8")
    readme = report_repo / "README.md"
    readme.write_text(f"# Demo\n\n{START}\n| stale |\n{END}\n\nAfter.\n", encoding="utf-8")
    monkeypatch.chdir(report_repo)
    assert cli.main(["eval", "report", "--check"]) == 1
    assert cli.main(["eval", "report"]) == 0
    text = readme.read_text(encoding="utf-8")
    assert "| stale |" not in text and "| Rules |" in text and text.endswith("After.\n")
    assert cli.main(["eval", "report", "--check"]) == 0
    readme.write_text(text.replace("| Rules |", "| Rules (edited) |"), encoding="utf-8")
    assert cli.main(["eval", "report", "--check"]) == 1
    readme.write_text("# Demo, markers removed\n", encoding="utf-8")
    assert cli.main(["eval", "report", "--check"]) == 2


def test_committed_readme_block_matches_the_config() -> None:
    """The real README has the markers and the config section that fills them."""
    config = json.loads((ROOT / "docs/benchmarks/config.json").read_text(encoding="utf-8"))
    parse_spec(config["readme"], "docs/benchmarks/config.json")
    text = (ROOT / "README.md").read_text(encoding="utf-8")
    assert text.count(START) == 1 and text.count(END) == 1


def _partial_index() -> dict[str, Any]:
    """The fast row complete on de + en; the other row run on de only (an older fixture)."""
    index = _index()
    fast, other = index["snapshots"]
    fast["languages"] = {"de": {"leak": 0.0}, "en": {"leak": 0.0331}}
    fast["missing_languages"] = []
    other["missing_languages"] = ["en"]
    other["all"]["leak"] = 0.0
    return index


def test_a_cell_missing_languages_is_marked_and_never_bold() -> None:
    """LAB-1656: a tool run on fewer languages is not pooled silently with complete rows."""
    spec = {"columns": [SPEC["columns"][0]], "rows": SPEC["rows"][:2]}
    block = render_block(_partial_index(), [], parse_spec(spec, "config"))
    # Both are 0.0 %, but the winner set includes a marked cell, so nothing is bold.
    assert "| **Fast** | 0.0 % |" in block
    assert "| Other | 0.0 % § |" in block
    assert "§ Run on fewer languages than the set has" in block
    assert "Other on Hand-written (no en)" in block


def test_over_masking_table_and_per_language_line() -> None:
    spec = parse_spec({**SPEC, "over_masking_table": True, "per_language": True}, "config")
    block = render_block(_partial_index(), [_counts("fast", 0.02, "new-fast")], spec)
    assert "Leak per language of the fast row on `smoke`: de 0.0 %, en 3.3 %." in block
    assert "| Over-masking | Hand-written (de+en, 3 docs) | Public (7) |" in block
    assert "| **Fast** | **1.1 %** | **27.9 %** |" in block  # the only number is the lowest
    assert "| Other | 30.0 % § | — |" in block
    assert "Over-masking of the fast row" not in block  # the table replaces the one-liner
    with pytest.raises(RecordError, match="per_language"):
        parse_spec({**SPEC, "per_language": "yes"}, "config")


def test_records_line_names_dataset_results_only_with_a_dataset_column() -> None:
    only_runs = {"columns": [SPEC["columns"][0]], "rows": SPEC["rows"]}
    block = render_block(_index(), [], parse_spec(only_runs, "config"))
    assert "every other cell is in the [run log](docs/benchmarks.md#run-log)." in block
    assert "eval/datasets/results/" not in block


def test_latency_line_quotes_one_cell_of_one_latency_record() -> None:
    index = {
        **_index(),
        "latency": [
            {
                "run_id": "lat-cpu",
                "hardware": "Test CPU",
                "cells": [
                    {
                        "concurrency": 1,
                        "stream": False,
                        "requests": 200,
                        "overhead_ms": {"p50": 33.6, "p95": 40.2},
                    },
                    {
                        "concurrency": 8,
                        "stream": False,
                        "requests": 200,
                        "overhead_ms": {"p50": 144.0, "p95": 178.0},
                    },
                ],
            }
        ],
    }
    lat = {"run": "lat-cpu", "concurrency": 1, "stream": False, "label": "Added on CPU"}
    block = render_block(index, [], parse_spec({**SPEC, "latency": lat}, "config"))
    assert "Added on CPU: p50 34 ms, p95 40 ms (200 requests, Test CPU; " in block
    assert "[record](eval/results/runs/lat-cpu.json))." in block
    with pytest.raises(RecordError, match="not a latency record"):
        render_block(index, [], parse_spec({**SPEC, "latency": {**lat, "run": "x"}}, "c"))
    with pytest.raises(RecordError, match="no cell"):
        render_block(index, [], parse_spec({**SPEC, "latency": {**lat, "concurrency": 4}}, "c"))
